"""The search behind Remark 5.1: every sublattice of K x K generated by the diagonal and one further pair,
and for each one a complete decision, by SAT, of whether some maximal sublattice has a complement that is
not an interval.  Needs python-sat.

A maximal sublattice that misses 0 or 1 is T - {0} or T - {1}, whose complement is an interval, so only
proper sublattices containing 0 and 1 matter.  One solver searches for such a sublattice S whose
complement is not an interval (some element of S lies between two elements of the complement, or the
join or meet of two elements of the complement lies in S); a second solver enlarges each model to a
maximal proper sublattice M.  If the complement of M is not an interval the lattice is a counterexample;
otherwise the clause "S is not inside M" is added and the search goes on.  UNSAT means every maximal
sublattice has an interval as its complement.

usage: python3 -I single_pair_search.py"""
import collections
import sys
from itertools import product

from pysat.solvers import Cadical153

COVERS = [(0, 1), (0, 2), (1, 3), (1, 4), (2, 4), (2, 7), (3, 5), (3, 6), (4, 9), (5, 10), (6, 8), (6, 9),
          (7, 12), (8, 10), (8, 11), (9, 12), (10, 13), (11, 13), (12, 11)]
n = 14
K = range(n)
le = [[i == j for j in K] for i in K]
for a, b in COVERS:
    le[a][b] = True
for k, i, j in product(K, K, K):
    if le[i][k] and le[k][j]:
        le[i][j] = True
J = [[min((u for u in K if le[a][u] and le[b][u]), key=lambda u: sum(le[w][u] for w in K)) for b in K] for a in K]
M = [[max((u for u in K if le[u][a] and le[u][b]), key=lambda u: sum(le[w][u] for w in K)) for b in K] for a in K]
pj = lambda p, q: (J[p[0]][q[0]], J[p[1]][q[1]])
pm = lambda p, q: (M[p[0]][q[0]], M[p[1]][q[1]])
ple = lambda p, q: le[p[0]][q[0]] and le[p[1]][q[1]]


def gen(S):
    S = set(S)
    while True:
        new = {pj(p, q) for p in S for q in S} | {pm(p, q) for p in S for q in S}
        if new <= S:
            return S
        S |= new


def counterexample(T):
    """None if every maximal sublattice of T has interval complement, else such a complement."""
    T = sorted(T)
    N = len(T)
    idx = {p: i for i, p in enumerate(T)}
    v = lambda i: i + 1
    LE = [[ple(p, q) for q in T] for p in T]
    JN = [[idx[pj(p, q)] for q in T] for p in T]
    MT = [[idx[pm(p, q)] for q in T] for p in T]
    bot = idx[(0, 0)]
    top = idx[(13, 13)]
    base = []
    for a in range(N):
        for b in range(a + 1, N):
            if not (LE[a][b] or LE[b][a]):
                base += [[-v(a), -v(b), v(JN[a][b])], [-v(a), -v(b), v(MT[a][b])]]
    ext = Cadical153(bootstrap_with=base)
    ext.add_clause([-v(i) for i in range(N)])
    srch = Cadical153(bootstrap_with=base)
    srch.add_clause([-v(i) for i in range(N)])
    srch.add_clause([v(bot)])
    srch.add_clause([v(top)])
    nv = N
    wit = []
    for z in range(N):
        below = [x for x in range(N) if x != z and LE[x][z]]
        above = [y for y in range(N) if y != z and LE[z][y]]
        if below and above:
            nv += 1
            wit.append(nv)
            srch.add_clause([-nv, v(z)])
            srch.add_clause([-nv] + [-v(x) for x in below])
            srch.add_clause([-nv] + [-v(y) for y in above])
    for x in range(N):
        for y in range(x + 1, N):
            if not (LE[x][y] or LE[y][x]):
                for t in (JN[x][y], MT[x][y]):
                    nv += 1
                    wit.append(nv)
                    srch.add_clause([-nv, -v(x)])
                    srch.add_clause([-nv, -v(y)])
                    srch.add_clause([-nv, v(t)])
    srch.add_clause(wit)

    def is_interval(C):
        lo = hi = C[0]
        for x in C:
            lo, hi = MT[lo][x], JN[hi][x]
        return sorted(x for x in range(N) if LE[lo][x] and LE[x][hi]) == sorted(C)

    while srch.solve():
        m = srch.get_model()
        S = {i for i in range(N) if m[i] > 0}
        while True:
            nv += 1
            ext.add_clause([-nv] + [v(c) for c in range(N) if c not in S])
            ok = ext.solve(assumptions=[v(i) for i in S] + [nv])
            mm = ext.get_model() if ok else None
            ext.add_clause([-nv])
            if not ok:
                break
            S = {i for i in range(N) if mm[i] > 0}
        C = [i for i in range(N) if i not in S]
        if not is_interval(C):
            return [T[i] for i in C]
        srch.add_clause([v(c) for c in C])
    return None


D = [(x, x) for x in K]
seen = {}
for p in product(K, K):
    if p[0] != p[1]:
        T = frozenset(gen(D + [p]))
        seen.setdefault(T, []).append(p)
sizes = collections.Counter(len(T) for T in seen)
fails = collections.Counter()
print(f'{len(seen)} distinct sublattices generated by the diagonal and one pair')
for T, gens in sorted(seen.items(), key=lambda t: (len(t[0]), sorted(t[1]))):
    C = counterexample(T)
    if C is not None:
        fails[len(T)] += 1
        print(f'  {len(T)} elements, generated with {sorted(gens)[0]}: complement {sorted(C)} is not an interval')
print('sizes:', ' '.join(f'{s}x{c}' for s, c in sorted(sizes.items())))
print('counterexamples:', ' '.join(f'{s}x{c}' for s, c in sorted(fails.items())))
expected = {26: 2, 47: 4, 56: 2}
if dict(fails) != expected or min(sizes) != 26 or sizes[26] != 2:
    sys.exit('unexpected result')
print('the two 26-element sublattices are the smallest, and both are counterexamples')
